import numpy as np
from scipy import stats
from sklearn.metrics import roc_auc_score
from sklearn.linear_model import LogisticRegression

MAX_DRIVERS = 5

def design(feats):
    # Find features with significant association (p < 0.05)
    sig_features = []
    for i, fid in enumerate(feats.ids):
        if feats.types[i] == 'derived':
            continue  # Skip derived features
        # Simple t-statistic approximation
        t_stat = np.corrcoef(feats.x[:, i], feats.y)[0, 1] * np.sqrt(feats.n - 2) / np.sqrt(1 - np.corrcoef(feats.x[:, i], feats.y)[0, 1]**2)
        p_val = 2 * (1 - stats.t.cdf(abs(t_stat), feats.n - 1))
        if p_val < 0.05:
            sig_features.append((fid, i, p_val))

    # Sort by significance (p-value)
    sig_features.sort(key=lambda x: x[2])

    # Remove near-duplicates based on correlation
    keep_features = set()
    corr_pairs = set()

    # Check correlations between features
    for i, fid1 in enumerate(feats.ids):
        for j, fid2 in enumerate(feats.ids):
            if i >= j:
                continue
            corr = np.corrcoef(feats.x[:, i], feats.x[:, j])[0, 1]
            if abs(corr) >= 0.6:
                corr_pairs.add((min(fid1, fid2), max(fid1, fid2)))

    # Select unique features
    for fid, idx, p_val in sig_features:
        # Check if this feature is correlated with any previously selected
        skip = False
        for prev_fid in keep_features:
            if (min(fid, prev_fid), max(fid, prev_fid)) in corr_pairs:
                skip = True
                break
        if not skip:
            keep_features.add(fid)

    # Try to find interaction terms among top features
    top_features = list(keep_features)[:10]  # Top 10 features
    best_products = []
    best_auc = 0

    # Try products of pairs
    for i, f1 in enumerate(top_features):
        for j, f2 in enumerate(top_features):
            if i >= j:
                continue
            col1 = feats.column(f1)
            col2 = feats.column(f2)
            prod = feats.x[:, col1] * feats.x[:, col2]

            # Fit logistic regression with product term
            X_cols = [feats.column(f) for f in top_features if f != f1 and f != f2]
            if X_cols:
                X = feats.x[:, X_cols]
                X = np.column_stack([X, prod])
            else:
                X = prod.reshape(-1, 1)

            model = LogisticRegression(penalty='l1', solver='liblinear', max_iter=1000)
            try:
                model.fit(X, feats.y)
                pred = model.predict_proba(X)[:, 1]
                auc = roc_auc_score(feats.y, pred)

                if auc > best_auc:
                    best_auc = auc
                    best_products = [(f1, f2)]
            except:
                continue

    # Return the best combination
    if best_products:
        f1, f2 = best_products[0]
        return Design(
            drivers=(f1, f2),
            columns=(f1, f2),
            products=((f1, f2),),
            loadings={f1: 1.0, f2: 1.0}
        )
    elif len(keep_features) > 0:
        # Just return top features without interaction
        top_fids = list(keep_features)[:MAX_DRIVERS]
        return Design(
            drivers=tuple(top_fids),
            columns=tuple(top_fids),
            products=(),
            loadings={fid: 1.0 for fid in top_fids}
        )
    else:
        return Design(
            drivers=(),
            columns=(),
            products=(),
            loadings={}
        )

